import { Injectable } from '@nestjs/common';
import { DataSource, Brackets } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { ContactEntity } from './contact.entity';
import { ContactListQueryDto } from './dto';

export type ContactCompanySummary = {
  id: string;
  name: string;
  isPrimary: boolean;
};

@Injectable()
export class ContactRepository extends BaseRepository<ContactEntity> {
  constructor(private dataSource: DataSource) {
    super(ContactEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: ContactListQueryDto) {
    const queryBuilder = this.createQueryBuilder('contact');

    const sortField = query.sort
      ? `contact.${query.sort}`
      : 'contact.createdAt';
    const sortOrder = query.order ? query.order.toUpperCase() : 'DESC';
    queryBuilder.orderBy(sortField, sortOrder as 'ASC' | 'DESC');

    queryBuilder.distinct(true);

    if (query.companyId) {
      queryBuilder
        .innerJoin(
          'contact_company_links',
          'companyLinkFilter',
          'companyLinkFilter."contactId" = contact.id',
        )
        .andWhere('companyLinkFilter."companyId" = :companyId', {
          companyId: query.companyId,
        });
    }

    if (query.q) {
      const searchValue = `%${query.q}%`;
      queryBuilder.andWhere(
        new Brackets((qb) => {
          qb.where('contact.name ILIKE :searchValue', { searchValue })
            .orWhere('contact.email ILIKE :searchValue', { searchValue })
            .orWhere('contact.phone ILIKE :searchValue', { searchValue })
            .orWhere('contact.role ILIKE :searchValue', { searchValue });
        }),
      );
    }

    if (query.role) {
      queryBuilder.andWhere('contact.role = :role', { role: query.role });
    }

    const offset = query.offset ?? 0;
    const limit = query.limit ?? 20;

    return queryBuilder.skip(offset).take(limit).getManyAndCount();
  }

  async findCompanySummariesByContactIds(contactIds: string[]) {
    if (contactIds.length === 0) {
      return new Map<string, ContactCompanySummary[]>();
    }

    const rows = await this.dataSource
      .createQueryBuilder()
      .select('link."contactId"', 'contactId')
      .addSelect('company.id', 'id')
      .addSelect('company.name', 'name')
      .addSelect('link."isPrimary"', 'isPrimary')
      .from('contact_company_links', 'link')
      .innerJoin('companies', 'company', 'company.id = link."companyId"')
      .where('link."contactId" IN (:...contactIds)', { contactIds })
      .orderBy('link."contactId"', 'ASC')
      .addOrderBy('link."isPrimary"', 'DESC')
      .addOrderBy('company.name', 'ASC')
      .getRawMany<{
        contactId: string;
        id: string;
        name: string;
        isPrimary: boolean;
      }>();

    const map = new Map<string, ContactCompanySummary[]>();

    rows.forEach((row) => {
      const existing = map.get(row.contactId) ?? [];
      existing.push({
        id: row.id,
        name: row.name,
        isPrimary: Boolean(row.isPrimary),
      });
      map.set(row.contactId, existing);
    });

    return map;
  }

  async findLinkedCompanyIds(contactId: string): Promise<string[]> {
    const rows = await this.dataSource
      .createQueryBuilder()
      .select('link."companyId"', 'companyId')
      .from('contact_company_links', 'link')
      .where('link."contactId" = :contactId', { contactId })
      .getRawMany<{ companyId: string }>();

    return rows.map((row) => row.companyId);
  }
}
import { HttpStatus, Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { ContactRepository, ContactCompanySummary } from './contact.repository';
import {
  CreateContactDto,
  UpdateContactDto,
  ContactListQueryDto,
  ContactCompanyInputDto,
} from './dto';
import { ContactEntity } from './contact.entity';
import { CompanyService } from '../company/company.module';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';

type ContactResponse = Omit<ContactEntity, 'companyId'> & {
  companies: ContactCompanySummary[];
};

@Injectable()
export class ContactService {
  constructor(
    private readonly contactRepository: ContactRepository,
    private readonly companyService: CompanyService,
    private readonly dataSource: DataSource,
  ) {}

  async createContact(dto: CreateContactDto): Promise<ContactResponse> {
    this.validateCompanyLinks(dto.companies, true);
    await this.assertCompaniesExist(dto.companies.map((company) => company.id));

    const primaryCompanyId =
      dto.companies.find((company) => company.isPrimary)?.id ?? null;

    if (!primaryCompanyId) {
      throw this.createValidationException({
        field: 'companies',
        message: 'Exactly one primary company link is required.',
      });
    }

    const contact = await this.dataSource.transaction(async (manager) => {
      const contactRepository = manager.getRepository(ContactEntity);

      const newContact = contactRepository.create({
        name: dto.name,
        email: dto.email,
        phone: dto.phone,
        role: dto.role ?? null,
        lastContactedAt: dto.lastContactedAt ?? null,
        companyId: primaryCompanyId,
      });

      const savedContact = await contactRepository.save(newContact);

      await manager
        .createQueryBuilder()
        .insert()
        .into('contact_company_links')
        .values(
          dto.companies.map((company) => ({
            contactId: savedContact.id,
            companyId: company.id,
            isPrimary: company.isPrimary,
          })),
        )
        .execute();

      return savedContact;
    });

    return await this.getContactById(contact.id);
  }

  async getContactsList(query: ContactListQueryDto) {
    const [items, total] = await this.contactRepository.findWithFilter(query);
    const companiesByContactId =
      await this.contactRepository.findCompanySummariesByContactIds(
        items.map((item) => item.id),
      );

    const limit = query.pageSize ?? 20;
    const page = query.page ?? 1;

    return {
      items: items.map((item) =>
        this.toContactResponse(item, companiesByContactId.get(item.id) ?? []),
      ),
      total,
      page,
      pageSize: limit,
      totalPages: Math.ceil(total / limit),
    };
  }

  async getContactById(id: string): Promise<ContactResponse> {
    const contact = await this.getContactEntityById(id);
    const companiesByContactId =
      await this.contactRepository.findCompanySummariesByContactIds([id]);

    return this.toContactResponse(contact, companiesByContactId.get(id) ?? []);
  }

  async updateContact(
    id: string,
    dto: UpdateContactDto,
  ): Promise<ContactResponse> {
    await this.getContactEntityById(id);

    if (dto.companies !== undefined) {
      this.validateCompanyLinks(dto.companies, true);
      await this.assertCompaniesExist(
        dto.companies.map((company) => company.id),
      );
    }

    await this.dataSource.transaction(async (manager) => {
      const contactRepository = manager.getRepository(ContactEntity);
      const contact = await contactRepository.findOne({ where: { id } });

      if (!contact) {
        throw this.createNotFoundException({
          resource: 'Contact',
          id,
          message: `Contact with ID ${id} not found`,
        });
      }

      const updatePayload: Partial<ContactEntity> = {
        ...(dto.name !== undefined ? { name: dto.name } : {}),
        ...(dto.email !== undefined ? { email: dto.email } : {}),
        ...(dto.phone !== undefined ? { phone: dto.phone } : {}),
        ...(dto.role !== undefined ? { role: dto.role } : {}),
        ...(dto.lastContactedAt !== undefined
          ? { lastContactedAt: dto.lastContactedAt }
          : {}),
      };

      if (dto.companies !== undefined) {
        const primaryCompanyId =
          dto.companies.find((company) => company.isPrimary)?.id ?? null;

        if (!primaryCompanyId) {
          throw this.createValidationException({
            field: 'companies',
            message: 'Exactly one primary company link is required.',
          });
        }

        updatePayload.companyId = primaryCompanyId;
      }

      const updatedContact = contactRepository.merge(contact, updatePayload);
      await contactRepository.save(updatedContact);

      if (dto.companies !== undefined) {
        await manager
          .createQueryBuilder()
          .delete()
          .from('contact_company_links')
          .where('"contactId" = :contactId', { contactId: id })
          .execute();

        await manager
          .createQueryBuilder()
          .insert()
          .into('contact_company_links')
          .values(
            dto.companies.map((company) => ({
              contactId: id,
              companyId: company.id,
              isPrimary: company.isPrimary,
            })),
          )
          .execute();
      }
    });

    return await this.getContactById(id);
  }

  async removeContact(id: string): Promise<void> {
    await this.getContactEntityById(id);
    await this.contactRepository.softDelete(id);
  }

  private async getContactEntityById(id: string): Promise<ContactEntity> {
    const contact = await this.contactRepository.findOne({ where: { id } });

    if (!contact) {
      throw this.createNotFoundException({
        resource: 'Contact',
        id,
        message: `Contact with ID ${id} not found`,
      });
    }

    return contact;
  }

  private toContactResponse(
    contact: ContactEntity,
    companies: ContactCompanySummary[],
  ): ContactResponse {
    const response = {
      ...contact,
      companies,
    } as ContactResponse & { companyId?: string };

    delete response.companyId;

    return response;
  }

  private async assertCompaniesExist(companyIds: string[]) {
    const uniqueCompanyIds = [...new Set(companyIds)];

    await Promise.all(
      uniqueCompanyIds.map(async (companyId) => {
        try {
          await this.companyService.getCompanyById(companyId);
        } catch (error) {
          if (error instanceof AppException && error.getStatus() === 404) {
            throw this.createNotFoundException({
              resource: 'Company',
              id: companyId,
              message: `Company with ID ${companyId} not found`,
            });
          }

          throw error;
        }
      }),
    );
  }

  private validateCompanyLinks(
    companies: ContactCompanyInputDto[] | undefined,
    required: boolean,
  ) {
    if (!companies || companies.length === 0) {
      if (!required) {
        return;
      }

      throw this.createValidationException({
        field: 'companies',
        message: 'At least one company link is required.',
      });
    }

    const uniqueCompanyIds = new Set(companies.map((company) => company.id));

    if (uniqueCompanyIds.size !== companies.length) {
      throw this.createValidationException({
        field: 'companies',
        message: 'Duplicate company links are not allowed.',
      });
    }

    const primaryCount = companies.filter(
      (company) => company.isPrimary,
    ).length;

    if (primaryCount !== 1) {
      throw this.createValidationException({
        field: 'companies',
        message: 'Exactly one primary company link is required.',
      });
    }
  }

  private createNotFoundException(input: {
    resource: 'Contact' | 'Company';
    id: string;
    message: string;
  }) {
    const { resource, id, message } = input;

    return new AppException({
      statusCode: HttpStatus.NOT_FOUND,
      code: BUSINESS_ERROR_CODES.NOT_FOUND,
      message,
      details: {
        resource,
        id,
      },
    });
  }

  private createValidationException(input: { field: string; message: string }) {
    return new AppException({
      statusCode: HttpStatus.BAD_REQUEST,
      code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
      message: input.message,
      details: {
        errors: [
          {
            field: input.field,
            messages: [input.message],
          },
        ],
      },
    });
  }
}
import {
  Patch,
  Controller,
  Delete,
  Get,
  Post,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { ContactService } from './contact.service';
import { CreateContactDto, UpdateContactDto, ContactListQueryDto } from './dto';
import { createUuidV4Pipe } from '../../common/pipes/uuid-v4.pipe';

@Controller('contacts')
export class ContactController {
  constructor(private readonly contactService: ContactService) {}

  /**
   * Create a new contact
   * Endpoint: POST /contacts[cite: 1]
   */
  @Post()
  async create(@Body() createContactDto: CreateContactDto) {
    return await this.contactService.createContact(createContactDto);
  }

  /**
   * List contacts with pagination and filtering
   * Endpoint: GET /contacts[cite: 1]
   */
  @Get()
  async findAll(@Query() query: ContactListQueryDto) {
    return await this.contactService.getContactsList(query);
  }

  /**
   * Get a single contact by ID
   * Endpoint: GET /contacts/:id[cite: 1]
   * Note: ParseUUIDPipe enforces the 400 INVALID_UUID constraint[cite: 1]
   */
  @Get(':id')
  async findOne(@Param('id', createUuidV4Pipe()) id: string) {
    return await this.contactService.getContactById(id);
  }

  /**
   * Partial update of a contact
   * Endpoint: POST /contacts/:id[cite: 1]
   * Note: The specification deliberately uses POST for partial updates (The POST double role convention)[cite: 1].
   */
  @Post(':id')
  @HttpCode(HttpStatus.OK)
  async update(
    @Param('id', createUuidV4Pipe()) id: string,
    @Body() updateContactDto: UpdateContactDto,
  ) {
    return await this.contactService.updateContact(id, updateContactDto);
  }

  @Patch(':id')
  @HttpCode(HttpStatus.OK)
  async patchUpdate(
    @Param('id', createUuidV4Pipe()) id: string,
    @Body() updateContactDto: UpdateContactDto,
  ) {
    return await this.contactService.updateContact(id, updateContactDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  remove(@Param('id', createUuidV4Pipe()) id: string): Promise<void> {
    return this.contactService.removeContact(id);
  }
}

