import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { DealEntity } from './deal.entity';
import { DealListQueryDto } from './dto';

export type DealContactLinkSummary = {
  contactId: string;
  role: string | null;
};

@Injectable()
export class DealRepository extends BaseRepository<DealEntity> {
  constructor(private dataSource: DataSource) {
    super(DealEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: DealListQueryDto) {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;

    const queryBuilder = this.createQueryBuilder('deal');

    if (query.stage) {
      queryBuilder.andWhere('deal.stage = :stage', { stage: query.stage });
    }

    if (query.companyId) {
      queryBuilder.andWhere('deal.companyId = :companyId', {
        companyId: query.companyId,
      });
    }

    const [items, total] = await queryBuilder
      .orderBy('deal.createdAt', 'DESC')
      .skip((page - 1) * pageSize)
      .take(pageSize)
      .getManyAndCount();

    return {
      items,
      total,
      page,
      pageSize,
      totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
    };
  }

  async findContactLinksByDealIds(dealIds: string[]) {
    if (dealIds.length === 0) {
      return new Map<string, DealContactLinkSummary[]>();
    }

    const rows = await this.dataSource
      .createQueryBuilder()
      .select('link."dealId"', 'dealId')
      .addSelect('link."contactId"', 'contactId')
      .addSelect('link."role"', 'role')
      .from('deal_contact_links', 'link')
      .where('link."dealId" IN (:...dealIds)', { dealIds })
      .orderBy('link."dealId"', 'ASC')
      .getRawMany<{
        dealId: string;
        contactId: string;
        role: string | null;
      }>();

    const map = new Map<string, DealContactLinkSummary[]>();

    rows.forEach((row) => {
      const existing = map.get(row.dealId) ?? [];
      existing.push({
        contactId: row.contactId,
        role: row.role,
      });
      map.set(row.dealId, existing);
    });

    return map;
  }

  async findContactLinksByDealId(dealId: string) {
    const map = await this.findContactLinksByDealIds([dealId]);
    return map.get(dealId) ?? [];
  }
}
