  it('creates a deal with multiple contacts and returns primaryContactId/contactLinks', async () => {
    // Verifies deal create supports many contact links and primary contact tracking.
    const companyId = await createCompany('deal-create');
    const contactA = await createContact('deal-create-a', companyId);
    const contactB = await createContact('deal-create-b', companyId);

    const payload = buildDealPayload('create', {
      companyId,
      contactLinks: [
        { contactId: contactA, role: 'decision-maker' },
        { contactId: contactB, role: 'legal' },
      ],
      primaryContactId: contactA,
      stage: 'qualified',
      expectedCloseDate: '2026-09-30',
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

