      name: payload.name,
      companyId,
      primaryContactId: contactA,
      contactLinks: [
        { contactId: contactA, role: 'decision-maker' },
        { contactId: contactB, role: 'legal' },
      ],
    });
    expect(createResponse.body).not.toHaveProperty('contactId');

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/deals/${createResponse.body.id}`)
