    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.id,
      companyId,
      primaryContactId: contactA,
      contactLinks: [
        { contactId: contactA, role: 'decision-maker' },
        { contactId: contactB, role: 'legal' },
      ],
      company: {
