import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  getTestDataSource,
  listConstraintNames,
  listIndexNames,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs the migrations on a clean schema', async () => {
    // Verifies migrations create the expected constraints and indexes.
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['fk_contacts_company_id']),
    );
    await expect(listIndexNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['idx_contacts_company_id']),
    );

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deals_company_id',
        'idx_deals_contact_id',
        'idx_deals_stage',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_company_links_contact_id',
        'fk_contact_company_links_company_id',
      ]),
    );
    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'idx_contact_company_links_company_id',
        'uq_contact_company_links_primary_contact',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contact_links_deal_id',
        'fk_deal_contact_links_contact_id',
      ]),
    );
    await expect(
      listIndexNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining(['idx_deal_contact_links_contact_id']),
    );
  });

  it('rolls back all migrations', async () => {
    // Verifies rollback removes all migration artifacts.
    await dataSource.runMigrations();
    await undoAllMigrations(dataSource);

    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.not.toContain('fk_contacts_company_id');
    await expect(listIndexNames(dataSource, 'contacts')).resolves.not.toContain(
      'idx_contacts_company_id',
    );

    await expect(
      listConstraintNames(dataSource, 'deals'),
    ).resolves.not.toContain('fk_deals_company_id');
    await expect(
      listConstraintNames(dataSource, 'deals'),
    ).resolves.not.toContain('fk_deals_contact_id');
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_company_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_contact_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_stage',
    );

    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('fk_contact_company_links_contact_id');
    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('fk_contact_company_links_company_id');
    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('idx_contact_company_links_company_id');
    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('uq_contact_company_links_primary_contact');

    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.not.toContain('fk_deal_contact_links_deal_id');
    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.not.toContain('fk_deal_contact_links_contact_id');
    await expect(
      listIndexNames(dataSource, 'deal_contact_links'),
    ).resolves.not.toContain('idx_deal_contact_links_contact_id');
  });

  it('can rerun migrations after rollback', async () => {
    // Verifies migrations can be applied again after full rollback.
    await dataSource.runMigrations();
    await undoAllMigrations(dataSource);
    await dataSource.runMigrations();

    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.toContain('fk_contacts_company_id');
    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_company_links_contact_id',
        'fk_contact_company_links_company_id',
      ]),
    );
    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contact_links_deal_id',
        'fk_deal_contact_links_contact_id',
      ]),
    );
  });

  it('prevents orphan foreign key values', async () => {
    // Verifies contact/deal foreign keys block orphan rows.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), $1, 'Orphan Contact', 'orphan@test.local', '0200-7777', 'User', NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_contacts_company_id/i);

    const [{ id: companyId }] = await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "email", "phone", "website", "status", "industry", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Migration Co', 'migration@test.local', '0200-8888', 'https://migration.local', '1', 'TECHNOLOGY', NOW(), NOW())
        RETURNING id
      `,
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "expectedCloseDate", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Contact', 1000, 'lead', $1, $2, NULL, NOW(), NOW())
        `,
        [companyId, '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1bb'],
      ),
    ).rejects.toThrow(/fk_deals_contact_id/i);

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "expectedCloseDate", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Company', 2000, 'lead', $1, NULL, NULL, NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1cc'],
      ),
    ).rejects.toThrow(/fk_deals_company_id/i);

    await expect(
      dataSource.query(
        `
          INSERT INTO "contact_company_links" ("contactId", "companyId", "isPrimary")
          VALUES ($1, $2, true)
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1dd', companyId],
      ),
    ).rejects.toThrow(/fk_contact_company_links_contact_id/i);

    await expect(
      dataSource.query(
        `
          INSERT INTO "deal_contact_links" ("dealId", "contactId", "role")
          VALUES ($1, $2, 'owner')
        `,
        [
          '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ee',
          '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ff',
        ],
      ),
    ).rejects.toThrow(/fk_deal_contact_links_deal_id/i);
  });
});

async function undoAllMigrations(dataSource: DataSource) {
  while (true) {
    const rows: Array<{ id: number }> = await dataSource.query(
      'SELECT id FROM "migrations" ORDER BY id DESC',
    );

    if (rows.length === 0) {
      break;
    }

    await dataSource.undoLastMigration();
  }
}

