    expect(detailResponse.body.companies).toHaveLength(2);
    expect(detailResponse.body.companies[0]).toMatchObject({
      id: primaryCompanyId,
      isPrimary: true,
    });
    expect(detailResponse.body).not.toHaveProperty('companyId');
  });

  it('rejects contacts with zero or invalid primary-company selections', async () => {
    // Verifies exactly-one-primary and non-empty link invariants.
    const companyId = await createCompany('contact-validation');

    const zeroCompanies = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(
        buildContactPayload('invalid-empty', {
          companies: [],
        }),
      )
      .expect(400);

    expect(zeroCompanies.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });

    const twoPrimaries = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(
        buildContactPayload('invalid-primary', {
          companies: [
            { id: companyId, isPrimary: true },
            {
              id: await createCompany('contact-validation-other'),
              isPrimary: true,
            },
          ],
        }),
      )
      .expect(400);

    expect(twoPrimaries.body).toMatchObject({
      success: false,
      statusCode: 400,
      code: 'VALIDATION_ERROR',
    });
  });

  it('filters contacts by any linked company (primary or secondary)', async () => {
    // Verifies companyId filter matches secondary links as well.
    const companyA = await createCompany('contact-filter-a');
    const companyB = await createCompany('contact-filter-b');

    await createContact('filter-primary', {
      companies: [
        { id: companyA, isPrimary: true },
        { id: companyB, isPrimary: false },
      ],
      name: 'codex-e2e-contact-filter-primary',
    });

    await createContact('filter-secondary', {
      companies: [{ id: companyB, isPrimary: true }],
      name: 'codex-e2e-contact-filter-secondary',
    });

    const response = await request(app.getHttpServer())
      .get(`/api/contacts?companyId=${companyB}&q=codex-e2e-contact-filter`)
      .expect(200);

    expect(response.body.total).toBe(2);
    expect(
      response.body.items.every((item: { companies: Array<{ id: string }> }) =>
        item.companies.some((company) => company.id === companyB),
      ),
    ).toBe(true);
  });

  it('updates contact company links with PATCH and preserves exactly one primary', async () => {
    // Verifies updates can replace full link sets and switch primaries atomically.
    const companyA = await createCompany('contact-update-a');
    const companyB = await createCompany('contact-update-b');
    const companyC = await createCompany('contact-update-c');
    const contactId = await createContact('update', {
      companies: [
        { id: companyA, isPrimary: true },
        { id: companyB, isPrimary: false },
      ],
    });

    const response = await request(app.getHttpServer())
      .patch(`/api/contacts/${contactId}`)
      .send({
        companies: [
          { id: companyB, isPrimary: false },
          { id: companyC, isPrimary: true },
        ],
        role: 'Technical Buyer',
      })
      .expect(200);

    expect(response.body).toMatchObject({
      id: contactId,
      role: 'Technical Buyer',
      companies: [
        { id: companyC, isPrimary: true },
        { id: companyB, isPrimary: false },
      ],
    });
    expect(response.body).not.toHaveProperty('companyId');
  });

  it('returns NOT_FOUND for unknown company or contact references', async () => {
    // Verifies create/update enforce existing references.
    const missingCompanyResponse = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(
        buildContactPayload('missing-company', {
          companies: [
            {
              id: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa',
              isPrimary: true,
            },
          ],
        }),
      )
      .expect(404);

    expect(missingCompanyResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'NOT_FOUND',
    });

    const unknownContactResponse = await request(app.getHttpServer())
      .patch('/api/contacts/7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ab')
      .send({ role: 'Updated' })
      .expect(404);

    expect(unknownContactResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'NOT_FOUND',
    });
  });

  it('soft deletes a contact', async () => {
    // Verifies soft-deleted contacts are no longer returned by the API.
    const companyId = await createCompany('contact-delete');
    const contactId = await createContact('delete', {
      companies: [{ id: companyId, isPrimary: true }],
    });

    await request(app.getHttpServer())
      .delete(`/api/contacts/${contactId}`)
      .expect(204);

    const detailResponse = await request(app.getHttpServer())
      .get(`/api/contacts/${contactId}`)
      .expect(404);

    expect(detailResponse.body).toMatchObject({
      success: false,
      statusCode: 404,
      code: 'NOT_FOUND',
    });
  });

  async function createCompany(scope: string): Promise<string> {
    companySeq += 1;

    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send({
        name: `codex-e2e-company-${scope}-${companySeq}`,
        email: `contact-company-${companySeq}@test.local`,
        phone: `0100-${String(companySeq).padStart(4, '0')}`,
        website: `https://contact-company-${companySeq}.example.com`,
      })
      .expect(201);

    return response.body.companyId;
  }

  async function createContact(
    scope: string,
    overrides: Partial<ContactPayload> = {},
  ): Promise<string> {
    const payload = buildContactPayload(scope, overrides);
    const response = await request(app.getHttpServer())
      .post('/api/contacts')
      .send(payload)
      .expect(201);

    return response.body.id;
  }

  function buildContactPayload(
    scope: string,
    overrides: Partial<ContactPayload> = {},
  ): ContactPayload {
    contactSeq += 1;

    return {
      companies: [
        {
          id: '00000000-0000-4000-8000-000000000001',
          isPrimary: true,
        },
      ],
      name: `codex-e2e-contact-${scope}-${contactSeq}`,
      email: `contact-${contactSeq}@test.local`,
      phone: `0200-${String(contactSeq).padStart(4, '0')}`,
      role: 'User',
      ...overrides,
    };
  }
});

type ContactPayload = {
  companies: Array<{
    id: string;
    isPrimary: boolean;
  }>;
  name: string;
  email: string;
  phone: string;
  role: string;
};

import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  getTestDataSource,
  listConstraintNames,
  listIndexNames,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs the migrations on a clean schema', async () => {
    // Verifies migrations create the expected constraints and indexes.
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['fk_contacts_company_id']),
    );
    await expect(listIndexNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['idx_contacts_company_id']),
    );

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deals_company_id',
        'idx_deals_contact_id',
        'idx_deals_stage',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_company_links_contact_id',
        'fk_contact_company_links_company_id',
      ]),
    );
    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'idx_contact_company_links_company_id',
        'uq_contact_company_links_primary_contact',
      ]),
    );

    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contact_links_deal_id',
        'fk_deal_contact_links_contact_id',
      ]),
    );
    await expect(
      listIndexNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining(['idx_deal_contact_links_contact_id']),
    );
  });

  it('rolls back all migrations', async () => {
    // Verifies rollback removes all migration artifacts.
    await dataSource.runMigrations();
    await undoAllMigrations(dataSource);

    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.not.toContain('fk_contacts_company_id');
    await expect(listIndexNames(dataSource, 'contacts')).resolves.not.toContain(
      'idx_contacts_company_id',
    );

    await expect(
      listConstraintNames(dataSource, 'deals'),
    ).resolves.not.toContain('fk_deals_company_id');
    await expect(
      listConstraintNames(dataSource, 'deals'),
    ).resolves.not.toContain('fk_deals_contact_id');
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_company_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_contact_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_stage',
    );

    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('fk_contact_company_links_contact_id');
    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('fk_contact_company_links_company_id');
    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('idx_contact_company_links_company_id');
    await expect(
      listIndexNames(dataSource, 'contact_company_links'),
    ).resolves.not.toContain('uq_contact_company_links_primary_contact');

    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.not.toContain('fk_deal_contact_links_deal_id');
    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.not.toContain('fk_deal_contact_links_contact_id');
    await expect(
      listIndexNames(dataSource, 'deal_contact_links'),
    ).resolves.not.toContain('idx_deal_contact_links_contact_id');
  });

  it('can rerun migrations after rollback', async () => {
    // Verifies migrations can be applied again after full rollback.
    await dataSource.runMigrations();
    await undoAllMigrations(dataSource);
    await dataSource.runMigrations();

    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.toContain('fk_contacts_company_id');
    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(
      listConstraintNames(dataSource, 'contact_company_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_company_links_contact_id',
        'fk_contact_company_links_company_id',
      ]),
    );
    await expect(
      listConstraintNames(dataSource, 'deal_contact_links'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contact_links_deal_id',
        'fk_deal_contact_links_contact_id',
      ]),
    );
  });

  it('prevents orphan foreign key values', async () => {
    // Verifies contact/deal foreign keys block orphan rows.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), $1, 'Orphan Contact', 'orphan@test.local', '0200-7777', 'User', NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_contacts_company_id/i);

    const [{ id: companyId }] = await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "email", "phone", "website", "status", "industry", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Migration Co', 'migration@test.local', '0200-8888', 'https://migration.local', '1', 'TECHNOLOGY', NOW(), NOW())
        RETURNING id
      `,
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "expectedCloseDate", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Contact', 1000, 'lead', $1, $2, NULL, NOW(), NOW())
        `,
        [companyId, '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1bb'],
      ),
    ).rejects.toThrow(/fk_deals_contact_id/i);

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "expectedCloseDate", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Company', 2000, 'lead', $1, NULL, NULL, NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1cc'],
      ),
    ).rejects.toThrow(/fk_deals_company_id/i);

    await expect(
      dataSource.query(
        `
          INSERT INTO "contact_company_links" ("contactId", "companyId", "isPrimary")
          VALUES ($1, $2, true)
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1dd', companyId],
      ),
    ).rejects.toThrow(/fk_contact_company_links_contact_id/i);

    await expect(
      dataSource.query(
        `
          INSERT INTO "deal_contact_links" ("dealId", "contactId", "role")
          VALUES ($1, $2, 'owner')
        `,
        [
          '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ee',
          '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ff',
        ],
      ),
    ).rejects.toThrow(/fk_deal_contact_links_deal_id/i);
  });
});

async function undoAllMigrations(dataSource: DataSource) {
  while (true) {
    const rows: Array<{ id: number }> = await dataSource.query(
      'SELECT id FROM "migrations" ORDER BY id DESC',
    );

    if (rows.length === 0) {
      break;
    }

    await dataSource.undoLastMigration();
  }
}

