const emptyValues = {
  companyId: '',
  contactLinks: [],
  primaryContactId: null,
  name: '',
  stage: 'lead',
  value: '',
  expectedCloseDate: '',
};
const stageOptions = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
];

function normalizeCloseDate(value) {
  if (!value) {
    return '';
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  return formatForDatetimeLocal(value).slice(0, 10);
}

function normalizeContactLinks(initialValues) {
  if (Array.isArray(initialValues?.contactLinks)) {
    return initialValues.contactLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role ?? '',
    }));
  }

  if (initialValues?.contactId) {
    return [{ contactId: initialValues.contactId, role: '' }];
  }

  return [];
}

