  const handleContactsChange = (_, selectedContactOptions) => {
    const selectedContactIds = selectedContactOptions.map((contact) => contact.id);

    setValues((current) => {
      const previousById = new Map(
        current.contactLinks.map((contactLink) => [contactLink.contactId, contactLink]),
      );

      const nextContactLinks = selectedContactIds.map((contactId) => ({
        contactId,
        role: previousById.get(contactId)?.role ?? '',
      }));

      const currentPrimaryStillSelected =
        current.primaryContactId && selectedContactIds.includes(current.primaryContactId)
          ? current.primaryContactId
          : null;

      return {
        ...current,
        contactLinks: nextContactLinks,
        primaryContactId:
          currentPrimaryStillSelected ||
          (nextContactLinks.length === 1 ? nextContactLinks[0].contactId : null),
      };
    });
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((contactLink) =>
        contactLink.contactId === contactId
          ? { ...contactLink, role }
          : contactLink,
      ),
    }));
  };

  const handlePrimaryContactChange = (contactId) => {
    setValues((current) => ({
      ...current,
      primaryContactId:
        current.primaryContactId === contactId ? null : contactId,
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyId: true, name: true, stage: true, value: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage.trim(),
      contactLinks: values.contactLinks.map((contactLink) => ({
        contactId: contactLink.contactId,
        role: contactLink.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId,
      expectedCloseDate: values.expectedCloseDate || null,
    };

    if (mode === 'create') {
      await onSubmit({
        ...payload,
        companyId: values.companyId,
      });
      return;
    }

    await onSubmit(payload);
  };

  return (
    <Dialog
      open={open}
      onClose={isPending ? undefined : onClose}
      fullWidth
      maxWidth="md"
    >
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            autoFocus
            label="Deal name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
