import { SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const EDGE_PREFIX = 'Edge Seed Company';
const EDGE_DEAL_PREFIX = 'Edge Seed Deal';

const MAX_COMPANY_NAME = `${EDGE_PREFIX} Long Name ${'X'.repeat(225)}`.slice(
  0,
  255,
);
const MAX_CONTACT_ROLE = `Role-${'Y'.repeat(95)}`.slice(0, 100);
const EDGE_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-lost',
] as const;

export const edgeCaseSeedScenario: SeedScenario = {
  name: 'edge-case',
  async run({ dataSource, now }) {
    const companyRepository = dataSource.getRepository(CompanyEntity);
    const contactRepository = dataSource.getRepository(ContactEntity);
    const dealRepository = dataSource.getRepository(DealEntity);

    await cleanupCompaniesByPrefixes({ dataSource, now }, [EDGE_PREFIX]);

    const companies = [
      buildCompany({
        name: `${EDGE_PREFIX} 00 Empty Contacts`,
        status: CompanyStatus.PENDING,
        email: null,
        phone: null,
        website: null,
      }),
      buildCompany({
        name: `${EDGE_PREFIX} 01 Missing Fields`,
        status: CompanyStatus.INACTIVE,
        email: null,
        phone: null,
        website: null,
        lastContactedAt: distributeRecentDate(now, 1, 25),
      }),
      buildCompany({
        name: MAX_COMPANY_NAME,
        status: CompanyStatus.ACTIVE,
        industry: Industry.TECHNOLOGY,
        lastContactedAt: distributeRecentDate(now, 2, 25),
      }),
      ...Array.from({ length: 22 }, (_, index) =>
        buildCompany({
          name: `${EDGE_PREFIX} ${String(index + 2).padStart(2, '0')} ${['Alpha', 'Sort', 'Filter', 'Pagination'][index % 4]} ${String(index + 1).padStart(2, '0')}`,
          status: [
            CompanyStatus.ACTIVE,
            CompanyStatus.INACTIVE,
            CompanyStatus.PENDING,
          ][index % 3],
          industry: [
            Industry.FINANCE,
            Industry.MANUFACTURING,
            Industry.RETAIL,
            Industry.OTHER,
          ][index % 4],
          email:
            index % 5 === 0 ? null : `edge-company-${index + 1}@baseline.local`,
          phone:
            index % 6 === 0
              ? null
              : `+1-415-55${String(index).padStart(2, '0')}`,
          website:
            index % 7 === 0
              ? null
              : `https://edge-company-${index + 1}.baseline.local`,
          lastContactedAt: distributeRecentDate(now, index + 3, 25),
        }),
      ),
    ];

    const savedCompanies = await companyRepository.save(
      companies.map((company) => companyRepository.create(company)),
    );

    let contactsCreated = 0;

    for (const [companyIndex, company] of savedCompanies.entries()) {
      if (companyIndex === 0) {
        continue;
      }

      const contactsForCompany =
        companyIndex === 1 ? 1 : 1 + (companyIndex % 3);

      for (
        let contactIndex = 0;
        contactIndex < contactsForCompany;
        contactIndex += 1
      ) {
        contactsCreated += 1;

        const contact = await contactRepository.save(
          contactRepository.create(
            buildContact({
              companyId: company.id,
              name:
                companyIndex === 2 && contactIndex === 0
                  ? `Contact ${'Z'.repeat(240)}`.slice(0, 255)
                  : `${['Alpha', 'Beta', 'Gamma', 'Omega'][contactIndex % 4]} Edge Contact ${companyIndex}-${contactIndex}`,
              email:
                contactIndex % 4 === 0
                  ? null
                  : `edge-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
              phone:
                contactIndex % 5 === 0
                  ? null
                  : `+1-628-44${companyIndex}${contactIndex}`,
              role:
                companyIndex === 2 && contactIndex === 0
                  ? MAX_CONTACT_ROLE
                  : ['Evaluator', 'Technical Buyer', 'Influencer'][
                      contactIndex % 3
                    ],
              lastContactedAt:
                companyIndex % 6 === 0 && contactIndex === 0
                  ? undefined
                  : distributeRecentDate(now, companyIndex + contactIndex, 40),
            }),
          ),
        );

        await dataSource
          .createQueryBuilder()
          .insert()
          .into('contact_company_links')
          .values({
            contactId: contact.id,
            companyId: company.id,
            isPrimary: true,
          })
          .execute();
      }
    }

    let dealsCreated = 0;

    for (const [companyIndex, company] of savedCompanies.entries()) {
      if (companyIndex >= 10) {
        break;
      }

      const contacts = await contactRepository.find({
        where: { companyId: company.id },
        order: { createdAt: 'ASC' },
      });

      const expectedCloseDate =
        companyIndex % 4 === 1
          ? null
          : new Date(
              Date.UTC(
                now.getUTCFullYear(),
                now.getUTCMonth(),
                now.getUTCDate() + 14 + companyIndex,
              ),
            )
              .toISOString()
              .slice(0, 10);

      const deal = await dealRepository.save(
        dealRepository.create(
          buildDeal({
            name: `${EDGE_DEAL_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`,
            value: 5000 + companyIndex * 1700,
            companyId: company.id,
            stage: EDGE_STAGES[companyIndex % EDGE_STAGES.length],
            contactId:
              companyIndex % 3 === 0 ? null : (contacts[0]?.id ?? null),
            expectedCloseDate,
          }),
        ),
      );

      if (deal.contactId) {
        await dataSource
          .createQueryBuilder()
          .insert()
          .into('deal_contact_links')
          .values({
            dealId: deal.id,
            contactId: deal.contactId,
            role: null,
          })
          .execute();
      }

      dealsCreated += 1;
    }

    return {
      scenario: 'edge-case',
      companiesCreated: savedCompanies.length,
      contactsCreated,
      dealsCreated,
      notes: [
        'Includes one company with zero contacts for empty-state testing.',
        'Creates 25 companies to exercise pagination and sorting.',
        'Adds null fields and max-length values for form, table, and deal edge cases.',
      ],
    };
  },
};
import { faker } from '@faker-js/faker';
import { ContactEntity } from '../../../modules/contact/contact.entity';

type BuildContactInput = {
  companyId: string;
  name: string;
  lastContactedAt?: Date;
  email?: string | null;
  phone?: string | null;
  role?: string | null;
};

const buildPhoneNumber = () =>
  `+1-${faker.string.numeric(3)}-${faker.string.numeric(3)}-${faker.string.numeric(4)}`;

export const buildContact = ({
  companyId,
  name,
  lastContactedAt,
  email,
  phone,
  role,
}: BuildContactInput): Partial<ContactEntity> => {
  const contact: Partial<ContactEntity> = {
    companyId,
    name,
  };

  if (email !== null) {
    contact.email =
      email ?? faker.internet.email({ firstName: name.split(' ')[0] });
  }

  if (phone !== null) {
    contact.phone = phone ?? buildPhoneNumber();
  }

  if (role !== null) {
    contact.role =
      role ??
      faker.helpers.arrayElement([
        'Decision Maker',
        'Champion',
        'Evaluator',
        'Procurement',
      ]);
  }

  if (lastContactedAt !== undefined) {
    contact.lastContactedAt = lastContactedAt;
  }

  return contact;
};
import { DealEntity } from '../../../modules/deal/deal.entity';

type BuildDealInput = {
  name: string;
  value: number;
  companyId: string;
  stage?: string;
  contactId?: string | null;
  expectedCloseDate?: string | null;
};

export const buildDeal = ({
  name,
  value,
  companyId,
  stage,
  contactId,
  expectedCloseDate,
}: BuildDealInput): Partial<DealEntity> => {
  const deal: Partial<DealEntity> = {
    name,
    value,
    companyId,
    stage: stage ?? 'lead',
  };

  if (contactId !== undefined) {
    deal.contactId = contactId;
  }

  if (expectedCloseDate !== undefined) {
    deal.expectedCloseDate = expectedCloseDate;
  }

  return deal;
};
import { DataSource } from 'typeorm';

export type SeedScenarioName = 'demo' | 'edge-case';

export type SeedSummary = {
  scenario: SeedScenarioName;
  companiesCreated: number;
  contactsCreated: number;
  dealsCreated: number;
  notes: string[];
};

export type SeedContext = {
  dataSource: DataSource;
  now: Date;
};

export type SeedScenario = {
  name: SeedScenarioName;
  run: (context: SeedContext) => Promise<SeedSummary>;
};
import 'reflect-metadata';
import { Logger } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DataSource } from 'typeorm';
import { AppModule } from '../../app.module';
import { demoSeedScenario } from './scenarios/demo.seed';
import { edgeCaseSeedScenario } from './scenarios/edge-case.seed';
import { SeedScenario, SeedScenarioName } from './seed.types';
import { resetSeedTables } from './seed.utils';

const logger = new Logger('Seed');

const scenarios: Record<SeedScenarioName, SeedScenario> = {
  demo: demoSeedScenario,
  'edge-case': edgeCaseSeedScenario,
};

const parseArgs = (argv: string[]) => {
  const scenarioName = (argv[0] ?? 'demo') as SeedScenarioName;
  const shouldReset = argv.includes('--reset');

  if (!(scenarioName in scenarios)) {
    throw new Error(
      `Unknown seed scenario "${scenarioName}". Use one of: ${Object.keys(scenarios).join(', ')}`,
    );
  }

  return {
    scenarioName,
    shouldReset,
  };
};

const run = async () => {
  const { scenarioName, shouldReset } = parseArgs(process.argv.slice(2));
  const app = await NestFactory.createApplicationContext(AppModule, {
    logger: ['error', 'warn', 'log'],
  });

  try {
    const dataSource = app.get(DataSource);

    if (shouldReset) {
      await resetSeedTables({ dataSource, now: new Date() });
      logger.log('Reset deals, contacts, and companies tables.');
    }

    const summary = await scenarios[scenarioName].run({
      dataSource,
      now: new Date(),
    });

    logger.log(
      `Scenario ${summary.scenario} completed: ${summary.companiesCreated} companies, ${summary.contactsCreated} contacts, ${summary.dealsCreated} deals.`,
    );

    for (const note of summary.notes) {
      logger.log(note);
    }
  } finally {
    await app.close();
  }
};

void run();

import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_COMPANY_PREFIX = 'Demo Seed Company';
const DEMO_DEAL_PREFIX = 'Demo Seed Deal';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
] as const;

type DemoCompanyRecord = {
  company: CompanyEntity;
  contactIds: string[];
};

const createDemoCompanies = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const createdCompanies: DemoCompanyRecord[] = [];
  let contactsCreated = 0;

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_COMPANY_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_COMPANY_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );

    const contactIds: string[] = [];
    const contactsForCompany = 2 + (companyIndex % 4);

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            companyId: company.id,
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      await dataSource
        .createQueryBuilder()
        .insert()
        .into('contact_company_links')
        .values({
          contactId: contact.id,
          companyId: company.id,
          isPrimary: true,
        })
        .execute();

      contactIds.push(contact.id);
    }

    createdCompanies.push({ company, contactIds });
  }

  if (
    createdCompanies.length >= 2 &&
    createdCompanies[0].contactIds.length > 0
  ) {
    const multiLinkedContactId = createdCompanies[0].contactIds[0];
    const secondaryCompanyId = createdCompanies[1].company.id;

    await dataSource
      .createQueryBuilder()
      .insert()
      .into('contact_company_links')
      .values({
        contactId: multiLinkedContactId,
        companyId: secondaryCompanyId,
        isPrimary: false,
      })
      .orIgnore()
      .execute();
  }

  return {
    createdCompanies,
    contactsCreated,
  };
};

const createDemoDeals = async (
  { dataSource, now }: SeedContext,
  companies: DemoCompanyRecord[],
) => {
  const dealRepository = dataSource.getRepository(DealEntity);
  let dealsCreated = 0;

  for (const [index, record] of companies.entries()) {
    const expectedCloseDate =
      index % 4 === 0
        ? null
        : new Date(
            Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()),
          );

    if (expectedCloseDate) {
      expectedCloseDate.setUTCDate(
        expectedCloseDate.getUTCDate() + 21 + index * 3,
      );
    }

    const dealContactLinks =
      index === 2 && record.contactIds.length >= 3
        ? [
            { contactId: record.contactIds[0], role: 'decision-maker' },
            { contactId: record.contactIds[1], role: 'legal' },
            { contactId: record.contactIds[2], role: 'it-lead' },
          ]
        : index % 3 === 0 || !record.contactIds[0]
          ? []
          : record.contactIds[0]
            ? [{ contactId: record.contactIds[0], role: null }]
            : [];

    const deal = await dealRepository.save(
      dealRepository.create(
        buildDeal({
          name: `${DEMO_DEAL_PREFIX} ${String(index + 1).padStart(2, '0')}`,
          value: 15000 + index * 4000,
          companyId: record.company.id,
          stage: DEAL_STAGES[index % DEAL_STAGES.length],
          contactId:
            index % 3 === 0
              ? null
              : (dealContactLinks.find((link) => link.contactId)?.contactId ??
                null),
          expectedCloseDate: expectedCloseDate
            ? expectedCloseDate.toISOString().slice(0, 10)
            : null,
        }),
      ),
    );

    if (dealContactLinks.length > 0) {
      await dataSource
        .createQueryBuilder()
        .insert()
        .into('deal_contact_links')
        .values(
          dealContactLinks.map((link) => ({
            dealId: deal.id,
            contactId: link.contactId,
            role: link.role,
          })),
        )
        .execute();
    }

    dealsCreated += 1;
  }

  return dealsCreated;
};

export const demoSeedScenario: SeedScenario = {
  name: 'demo',
  async run(context) {
    faker.seed(20260703);

    const { createdCompanies, contactsCreated } =
      await createDemoCompanies(context);
    const dealsCreated = await createDemoDeals(context, createdCompanies);

    return {
      scenario: 'demo',
      companiesCreated: createdCompanies.length,
      contactsCreated,
      dealsCreated,
      notes: [
        'Creates 10 companies with 2-5 contacts each, including a multi-company contact link.',
        'Creates 10 deals across five pipeline stages.',
        'Adds one deal with three linked contacts and distinct roles.',
        'Distributes lastContactedAt timestamps across the last 30 days.',
      ],
    };
  },
};

import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const EDGE_PREFIX = 'Edge Seed Company';
const EDGE_DEAL_PREFIX = 'Edge Seed Deal';

const MAX_COMPANY_NAME = `${EDGE_PREFIX} Long Name ${'X'.repeat(225)}`.slice(
  0,
  255,
);
const MAX_CONTACT_ROLE = `Role-${'Y'.repeat(95)}`.slice(0, 100);
const EDGE_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-lost',
] as const;

export const edgeCaseSeedScenario: SeedScenario = {
  name: 'edge-case',
  async run({ dataSource, now }) {
    const companyRepository = dataSource.getRepository(CompanyEntity);
    const contactRepository = dataSource.getRepository(ContactEntity);
    const dealRepository = dataSource.getRepository(DealEntity);

    await cleanupCompaniesByPrefixes({ dataSource, now }, [EDGE_PREFIX]);

    const companies = [
      buildCompany({
        name: `${EDGE_PREFIX} 00 Empty Contacts`,
        status: CompanyStatus.PENDING,
        email: null,
        phone: null,
        website: null,
      }),
      buildCompany({
        name: `${EDGE_PREFIX} 01 Missing Fields`,
        status: CompanyStatus.INACTIVE,
        email: null,
        phone: null,
        website: null,
        lastContactedAt: distributeRecentDate(now, 1, 25),
      }),
      buildCompany({
        name: MAX_COMPANY_NAME,
        status: CompanyStatus.ACTIVE,
        industry: Industry.TECHNOLOGY,
        lastContactedAt: distributeRecentDate(now, 2, 25),
      }),
      ...Array.from({ length: 22 }, (_, index) =>
        buildCompany({
          name: `${EDGE_PREFIX} ${String(index + 2).padStart(2, '0')} ${['Alpha', 'Sort', 'Filter', 'Pagination'][index % 4]} ${String(index + 1).padStart(2, '0')}`,
          status: [
            CompanyStatus.ACTIVE,
            CompanyStatus.INACTIVE,
            CompanyStatus.PENDING,
          ][index % 3],
          industry: [
            Industry.FINANCE,
            Industry.MANUFACTURING,
            Industry.RETAIL,
            Industry.OTHER,
          ][index % 4],
          email:
            index % 5 === 0 ? null : `edge-company-${index + 1}@baseline.local`,
          phone:
            index % 6 === 0
              ? null
              : `+1-415-55${String(index).padStart(2, '0')}`,
          website:
            index % 7 === 0
              ? null
              : `https://edge-company-${index + 1}.baseline.local`,
          lastContactedAt: distributeRecentDate(now, index + 3, 25),
        }),
      ),
    ];

    const savedCompanies = await companyRepository.save(
      companies.map((company) => companyRepository.create(company)),
    );

    let contactsCreated = 0;

    for (const [companyIndex, company] of savedCompanies.entries()) {
      if (companyIndex === 0) {
        continue;
      }

      const contactsForCompany =
        companyIndex === 1 ? 1 : 1 + (companyIndex % 3);

      for (
        let contactIndex = 0;
        contactIndex < contactsForCompany;
        contactIndex += 1
      ) {
        contactsCreated += 1;

        const contact = await contactRepository.save(
          contactRepository.create(
            buildContact({
              companyId: company.id,
              name:
                companyIndex === 2 && contactIndex === 0
                  ? `Contact ${'Z'.repeat(240)}`.slice(0, 255)
                  : `${['Alpha', 'Beta', 'Gamma', 'Omega'][contactIndex % 4]} Edge Contact ${companyIndex}-${contactIndex}`,
              email:
                contactIndex % 4 === 0
                  ? null
                  : `edge-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
              phone:
                contactIndex % 5 === 0
                  ? null
                  : `+1-628-44${companyIndex}${contactIndex}`,
              role:
                companyIndex === 2 && contactIndex === 0
                  ? MAX_CONTACT_ROLE
                  : ['Evaluator', 'Technical Buyer', 'Influencer'][
                      contactIndex % 3
                    ],
              lastContactedAt:
                companyIndex % 6 === 0 && contactIndex === 0
                  ? undefined
                  : distributeRecentDate(now, companyIndex + contactIndex, 40),
            }),
          ),
        );

        await dataSource
          .createQueryBuilder()
          .insert()
          .into('contact_company_links')
          .values({
            contactId: contact.id,
            companyId: company.id,
            isPrimary: true,
          })
          .execute();
      }
    }

    let dealsCreated = 0;

    for (const [companyIndex, company] of savedCompanies.entries()) {
      if (companyIndex >= 10) {
        break;
      }

      const contacts = await contactRepository.find({
        where: { companyId: company.id },
        order: { createdAt: 'ASC' },
      });

      const expectedCloseDate =
        companyIndex % 4 === 1
          ? null
          : new Date(
              Date.UTC(
                now.getUTCFullYear(),
                now.getUTCMonth(),
                now.getUTCDate() + 14 + companyIndex,
              ),
            )
              .toISOString()
              .slice(0, 10);

      const deal = await dealRepository.save(
        dealRepository.create(
          buildDeal({
            name: `${EDGE_DEAL_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`,
            value: 5000 + companyIndex * 1700,
            companyId: company.id,
            stage: EDGE_STAGES[companyIndex % EDGE_STAGES.length],
            contactId:
              companyIndex % 3 === 0 ? null : (contacts[0]?.id ?? null),
            expectedCloseDate,
          }),
        ),
      );

      if (deal.contactId) {
        await dataSource
          .createQueryBuilder()
          .insert()
          .into('deal_contact_links')
          .values({
            dealId: deal.id,
            contactId: deal.contactId,
            role: null,
          })
          .execute();
      }

      dealsCreated += 1;
    }

    return {
      scenario: 'edge-case',
      companiesCreated: savedCompanies.length,
      contactsCreated,
      dealsCreated,
      notes: [
        'Includes one company with zero contacts for empty-state testing.',
        'Creates 25 companies to exercise pagination and sorting.',
        'Adds null fields and max-length values for form, table, and deal edge cases.',
      ],
    };
  },
};

import {
  Alert,
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Snackbar,
  Typography,
  Stack,
} from '@mui/material';
import PlusOutlined from '@ant-design/icons/PlusOutlined';
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';

import { isTransportError } from 'api/request';
import { DataTablePagination } from '../../components/Table/Pagination/Pagination';
import { DataTableShell } from '../../components/Table/Shell/Shell';
import { ContactFormDialog } from './ContactForm';
import { ContactTable } from './ContactTable';

import {
  useContactList,
  useCreateContact,
  useDeleteContact,
  useUpdateContact,
} from './contactQueries';

function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function ContactsPage() {
  const navigate = useNavigate();
  const createContact = useCreateContact();
  const updateContact = useUpdateContact();
  const deleteContact = useDeleteContact();
  const [formState, setFormState] = useState({ open: false, mode: 'create', contact: null });
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [feedback, setFeedback] = useState({ open: false, severity: 'success', message: '' });
  const [searchInput, setSearchInput] = useState('');
  const [listQuery, setListQuery] = useState({
    page: 1,
    pageSize: 10,
  });
  const contactsQuery = useContactList(listQuery);

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createContact.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Contact created.',
        });
      } else {
        await updateContact.mutateAsync({
          id: formState.contact.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Contact updated.',
        });
      }

      setFormState({ open: false, mode: 'create', contact: null });
    } catch (error) {
      // Transport-level failures (network/5xx) are already toasted globally
      // (see App.jsx); only surface business errors here.
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Contact request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteContact.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Contact deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(searchInput.trim() ? { q: searchInput.trim() } : { q: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setListQuery({ page: 1, pageSize: listQuery.pageSize });
  };

  const handlePageChange = (page) => {
    setListQuery((current) => ({ ...current, page }));
  };

  const handlePageSizeChange = (pageSize) => {
    setListQuery((current) => ({ ...current, page: 1, pageSize }));
  };

  const contactPage = contactsQuery.data;
  const contactItems = contactPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Customers"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Search by name, email, phone, or role"
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() =>
              setFormState({
                open: true,
                mode: 'create',
                contact: null,
              })
            }
          >
            Add Contact
          </Button>
        )}
        loading={contactsQuery.isLoading}
        error={
          contactsQuery.isError && !isTransportError(contactsQuery.error)
            ? extractErrorMessage(contactsQuery.error, 'Failed to load contacts.')
            : null
        }
        isEmpty={!contactsQuery.isLoading && !contactsQuery.isError && contactItems.length === 0}
        emptyTitle="No matching contacts"
        emptyDescription="Try broadening the search or clearing the current filters."
        pagination={
          contactPage && contactPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={contactPage.page}
                pageSize={contactPage.pageSize}
                total={contactPage.total}
                totalPages={contactPage.totalPages}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
              />
            </Box>
          ) : null
        }
      >
        <ContactTable
          contacts={contactItems}
          onDelete={setDeleteTarget}
          onEdit={(contact) =>
            setFormState({
              open: true,
              mode: 'edit',
              contact,
            })
          }
          onView={(contact) => navigate(`/contacts/${contact.id}`)}
        />
      </DataTableShell>

      <ContactFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.contact}
        isPending={createContact.isPending || updateContact.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', contact: null })}
        onSubmit={handleFormSubmit}
      />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)}>
        <DialogTitle>Delete contact</DialogTitle>
        <DialogContent>
          <Typography>
             Delete {deleteTarget?.name}? This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDelete}>
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

