  const secondaryCount = Math.max(companies.length - 1, 0);

  return (
    <Stack direction="row" spacing={1} alignItems="center">
      <Typography>{primaryCompany.name || primaryCompany.id}</Typography>
      {secondaryCount > 0 ? (
        <Chip size="small" label={`+${secondaryCount}`} color="info" />
      ) : null}
    </Stack>
  );
}

