import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  MenuItem,
  Radio,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';

import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const emptyValues = {
  companyId: '',
  contactLinks: [],
  primaryContactId: null,
  name: '',
  stage: 'lead',
  value: '',
  expectedCloseDate: '',
};
const stageOptions = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
];

function normalizeCloseDate(value) {
  if (!value) {
    return '';
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  return formatForDatetimeLocal(value).slice(0, 10);
}

function normalizeContactLinks(initialValues) {
  if (Array.isArray(initialValues?.contactLinks)) {
    return initialValues.contactLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role ?? '',
    }));
  }

  if (initialValues?.contactId) {
    return [{ contactId: initialValues.contactId, role: '' }];
  }

  return [];
}

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyId: false,
    name: false,
    stage: false,
    value: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    companyId: values.companyId || undefined,
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = values.companyId ? contactsQuery.data?.items ?? [] : [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const selectedContacts = useMemo(
    () =>
      values.contactLinks
        .map((link) =>
          contactOptions.find((contact) => contact.id === link.contactId),
        )
        .filter(Boolean),
    [contactOptions, values.contactLinks],
  );

  const parsedValue = Number(values.value);
  const isValueValid =
    values.value !== '' && Number.isFinite(parsedValue) && parsedValue >= 0;
  const linkedContactIds = new Set(
    values.contactLinks.map((contactLink) => contactLink.contactId),
  );

  const errors = {
    companyId: !values.companyId ? 'Company is required.' : '',
    name: !values.name?.trim()
      ? 'Name is required.'
      : values.name.trim().length > 255
        ? 'Name must be 255 characters or fewer.'
        : '',
    stage: !values.stage?.trim()
      ? 'Stage is required.'
      : values.stage.trim().length > 100
        ? 'Stage must be 100 characters or fewer.'
        : '',
    value:
      values.value === ''
        ? 'Value is required.'
        : !isValueValid
          ? 'Value must be a non-negative number.'
          : '',
    primaryContactId:
      values.primaryContactId && !linkedContactIds.has(values.primaryContactId)
        ? 'Primary contact must be one of the linked contacts.'
        : '',
  };

  const isFormValid =
    !errors.companyId &&
    !errors.name &&
    !errors.stage &&
    !errors.value &&
    !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    const initialContactLinks = normalizeContactLinks(initialValues);
    const initialPrimaryContactId =
      initialValues?.primaryContactId ?? initialValues?.contactId ?? null;

    setValues({
      ...emptyValues,
      ...initialValues,
      companyId: initialValues?.companyId || '',
      contactLinks: initialContactLinks,
      primaryContactId:
        initialPrimaryContactId &&
        initialContactLinks.some(
          (contactLink) => contactLink.contactId === initialPrimaryContactId,
        )
          ? initialPrimaryContactId
          : initialContactLinks.length === 1
            ? initialContactLinks[0].contactId
            : null,
      stage: initialValues?.stage || 'lead',
      value:
        initialValues?.value === null || initialValues?.value === undefined
          ? ''
          : String(initialValues.value),
      expectedCloseDate: normalizeCloseDate(initialValues?.expectedCloseDate),
    });
    setTouched({ companyId: false, name: false, stage: false, value: false });
  }, [initialValues, open]);

  useEffect(() => {
    if (values.contactLinks.length === 0) {
      if (values.primaryContactId) {
        setValues((current) => ({ ...current, primaryContactId: null }));
      }
      return;
    }

    const selectedContactIds = new Set(contactOptions.map((contact) => contact.id));
    const prunedLinks = values.contactLinks.filter((contactLink) =>
      selectedContactIds.has(contactLink.contactId),
    );

    if (prunedLinks.length !== values.contactLinks.length) {
      setValues((current) => {
        const nextPrimary = prunedLinks.some(
          (contactLink) => contactLink.contactId === current.primaryContactId,
        )
          ? current.primaryContactId
          : prunedLinks.length === 1
            ? prunedLinks[0].contactId
            : null;

        return {
          ...current,
          contactLinks: prunedLinks,
          primaryContactId: nextPrimary,
        };
      });
    }
  }, [contactOptions, values.contactLinks, values.primaryContactId]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: null,
    }));
  };

  const handleContactsChange = (_, selectedContactOptions) => {
    const selectedContactIds = selectedContactOptions.map((contact) => contact.id);

    setValues((current) => {
      const previousById = new Map(
        current.contactLinks.map((contactLink) => [contactLink.contactId, contactLink]),
      );

      const nextContactLinks = selectedContactIds.map((contactId) => ({
        contactId,
        role: previousById.get(contactId)?.role ?? '',
      }));

      const currentPrimaryStillSelected =
        current.primaryContactId && selectedContactIds.includes(current.primaryContactId)
          ? current.primaryContactId
          : null;

      return {
        ...current,
        contactLinks: nextContactLinks,
        primaryContactId:
          currentPrimaryStillSelected ||
          (nextContactLinks.length === 1 ? nextContactLinks[0].contactId : null),
      };
    });
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((contactLink) =>
        contactLink.contactId === contactId
          ? { ...contactLink, role }
          : contactLink,
      ),
    }));
  };

  const handlePrimaryContactChange = (contactId) => {
    setValues((current) => ({
      ...current,
      primaryContactId:
        current.primaryContactId === contactId ? null : contactId,
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyId: true, name: true, stage: true, value: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage.trim(),
      contactLinks: values.contactLinks.map((contactLink) => ({
        contactId: contactLink.contactId,
        role: contactLink.role?.trim() || null,
      })),
      primaryContactId: values.primaryContactId,
      expectedCloseDate: values.expectedCloseDate || null,
    };

    if (mode === 'create') {
      await onSubmit({
        ...payload,
        companyId: values.companyId,
      });
      return;
    }

    await onSubmit(payload);
  };

  return (
    <Dialog
      open={open}
      onClose={isPending ? undefined : onClose}
      fullWidth
      maxWidth="md"
    >
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            autoFocus
            label="Deal name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Value"
              type="number"
              slotProps={{ htmlInput: { min: 0, step: '0.01' } }}
              value={values.value}
              onBlur={handleBlur('value')}
              onChange={handleChange('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            <TextField
              required
              fullWidth
              label="Stage"
              value={values.stage}
              onBlur={handleBlur('stage')}
              onChange={handleChange('stage')}
              error={touched.stage && Boolean(errors.stage)}
              helperText={touched.stage ? errors.stage : undefined}
              select
            >
              {stageOptions.map((stage) => (
                <MenuItem key={stage} value={stage}>
                  {stage}
                </MenuItem>
              ))}
            </TextField>
          </Stack>

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            disabled={mode === 'edit'}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : mode === 'edit'
                        ? 'Company is immutable once a deal is created.'
                        : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            multiple
            fullWidth
            options={contactOptions}
            value={selectedContacts}
            loading={contactsQuery.isLoading && Boolean(values.companyId)}
            disabled={!values.companyId}
            onChange={handleContactsChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              !values.companyId
                ? 'Select a company first'
                : contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                label="Linked contacts"
                helperText={
                  contactsQuery.isError && values.companyId
                    ? 'Failed to load contacts.'
                    : 'Deals can have zero or more contacts.'
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading && values.companyId ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          {values.contactLinks.length > 0 ? (
            <Stack spacing={1.25}>
              <Typography variant="subtitle2" color="text.secondary">
                Contact roles and primary
              </Typography>

              {values.contactLinks.map((contactLink) => {
                const contactName =
                  contactOptions.find((contact) => contact.id === contactLink.contactId)
                    ?.name || contactLink.contactId;

                return (
                  <Stack
                    key={contactLink.contactId}
                    direction={{ xs: 'column', md: 'row' }}
                    spacing={1.5}
                    sx={{ alignItems: { md: 'center' } }}
                  >
                    <Typography sx={{ minWidth: { md: '14rem' } }}>{contactName}</Typography>
                    <TextField
                      fullWidth
                      label="Role (optional)"
                      value={contactLink.role}
                      onChange={(event) =>
                        handleContactRoleChange(contactLink.contactId, event.target.value)
                      }
                    />
                    <FormControlLabel
                      control={
                        <Radio
                          checked={values.primaryContactId === contactLink.contactId}
                          onChange={() =>
                            handlePrimaryContactChange(contactLink.contactId)
                          }
                        />
                      }
                      label="Primary"
                    />
                  </Stack>
                );
              })}

              {errors.primaryContactId ? (
                <Typography color="error" variant="caption">
                  {errors.primaryContactId}
                </Typography>
              ) : null}
            </Stack>
          ) : null}

          <TextField
            fullWidth
            label="Expected close date"
            type="date"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
          />

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  FormHelperText,
  Radio,
  RadioGroup,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';

const emptyValues = {
  companies: [],
  name: '',
  email: '',
  phone: '',
  role: '',
  lastContactedAt: '',
};

function normalizeCompanies(inputCompanies = [], fallbackCompanyId) {
  if (Array.isArray(inputCompanies) && inputCompanies.length > 0) {
    return inputCompanies.map((company, index) => ({
      id: company.id,
      isPrimary:
        company.isPrimary === true ||
        (index === 0 && !inputCompanies.some((item) => item.isPrimary)),
    }));
  }

  if (fallbackCompanyId) {
    return [{ id: fallbackCompanyId, isPrimary: true }];
  }

  return [];
}

function countPrimaryCompanies(companies) {
  return companies.filter((company) => company.isPrimary).length;
}

export function ContactFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companies: false,
    name: false,
    email: false,
    phone: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = companiesQuery.data?.items ?? [];

  const selectedCompanies = useMemo(
    () =>
      values.companies
        .map((selectedCompany) =>
          companyOptions.find((company) => company.id === selectedCompany.id),
        )
        .filter(Boolean),
    [companyOptions, values.companies],
  );

  const primaryCompanyId =
    values.companies.find((company) => company.isPrimary)?.id ?? '';

  const phoneDigits = values.phone?.replace(/[^0-9]/g, '') || '';

  const errors = {
    companies:
      values.companies.length === 0
        ? 'At least one company is required.'
        : countPrimaryCompanies(values.companies) !== 1
          ? 'Select exactly one primary company.'
          : '',
    name: !values.name?.trim() ? 'Name is required.' : '',
    email: !values.email?.trim()
      ? 'Email is required.'
      : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)
        ? 'Invalid email format.'
        : '',
    phone: !values.phone?.trim()
      ? 'Phone is required.'
      : !values.phone.trim().startsWith('+')
        ? 'Must start with "+" and country code (e.g., +86).'
        : phoneDigits.length < 8 || phoneDigits.length > 15
          ? 'Invalid phone number length (8-15 digits required).'
          : '',
  };

  const isFormValid =
    !errors.companies && !errors.name && !errors.email && !errors.phone;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      companies: normalizeCompanies(
        initialValues?.companies,
        initialValues?.companyId,
      ),
      lastContactedAt: formatForDatetimeLocal(initialValues?.lastContactedAt),
    });
    setTouched({ companies: false, name: false, email: false, phone: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompaniesChange = (_, selectedCompanyOptions) => {
    const selectedCompanyIds = selectedCompanyOptions.map((company) => company.id);

    setValues((current) => {
      const previousById = new Map(
        current.companies.map((company) => [company.id, company]),
      );

      const nextCompanies = selectedCompanyIds.map((companyId) => ({
        id: companyId,
        isPrimary: previousById.get(companyId)?.isPrimary ?? false,
      }));

      if (nextCompanies.length === 1) {
        nextCompanies[0].isPrimary = true;
      } else if (nextCompanies.length > 1) {
        const existingPrimary = nextCompanies.find((company) => company.isPrimary);

        if (!existingPrimary) {
          nextCompanies[0].isPrimary = true;
        }
      }

      return {
        ...current,
        companies: nextCompanies,
      };
    });
  };

  const handlePrimaryCompanyChange = (event) => {
    const selectedPrimaryId = event.target.value;

    setValues((current) => ({
      ...current,
      companies: current.companies.map((company) => ({
        ...company,
        isPrimary: company.id === selectedPrimaryId,
      })),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companies: true, name: true, email: true, phone: true });

    if (!isFormValid) {
      return;
    }

    const payload = {
      companies: values.companies,
      name: values.name.trim(),
      email: values.email.trim(),
      phone: values.phone.trim(),
      role: values.role?.trim() || null,
      lastContactedAt: values.lastContactedAt
        ? new Date(values.lastContactedAt).toISOString()
        : null,
    };

    await onSubmit(payload);
  };

  return (
    <Dialog
      open={open}
      onClose={isPending ? undefined : onClose}
      fullWidth
      maxWidth="sm"
    >
      <DialogTitle>{mode === 'create' ? 'Create contact' : 'Edit contact'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            multiple
            fullWidth
            options={companyOptions}
            value={selectedCompanies}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companies')}
            onChange={handleCompaniesChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'
            }
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Companies"
                error={touched.companies && Boolean(errors.companies)}
                helperText={
                  touched.companies
                    ? errors.companies
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}

            )}
          />

          {values.companies.length > 0 ? (
            <FormControl
              error={touched.companies && Boolean(errors.companies)}
              component="fieldset"
            >
              <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 0.5 }}>
                Primary company
              </Typography>
              <RadioGroup
                value={primaryCompanyId}
                onChange={handlePrimaryCompanyChange}
                name="primary-company"
              >
                {values.companies.map((company) => {
                  const companyName =
                    companyOptions.find((option) => option.id === company.id)?.name ||
                    company.id;

                  return (
                    <FormControlLabel
                      key={company.id}
                      value={company.id}
                      control={<Radio size="small" />}
                      label={companyName}
                    />
                  );
                })}
              </RadioGroup>
              {touched.companies && errors.companies ? (
                <FormHelperText>{errors.companies}</FormHelperText>
              ) : null}
            </FormControl>
          ) : null}

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Email"
              type="email"
              value={values.email}
              onBlur={handleBlur('email')}
              onChange={handleChange('email')}
              error={touched.email && Boolean(errors.email)}
              helperText={touched.email ? errors.email : undefined}
            />
            <TextField
              required
              fullWidth
              label="Phone"
              type="tel"
              placeholder="+00 00000000000"
              value={values.phone}
              onBlur={handleBlur('phone')}
              onChange={handleChange('phone')}
              error={touched.phone && Boolean(errors.phone)}
              helperText={touched.phone ? errors.phone : undefined}
            />
          </Stack>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              fullWidth
              label="Role"
              value={values.role || ''}
              onChange={handleChange('role')}
              placeholder="e.g. Manager, User, Admin"
            />

            <TextField
              fullWidth
              label="Last Contacted At"
              type="datetime-local"
              InputLabelProps={{ shrink: true }}
              value={values.lastContactedAt}
              onChange={handleChange('lastContactedAt')}
            />
          </Stack>

          {mode === 'edit' && initialValues?.createdAt ? (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('en', {
                dateStyle: 'medium',
                timeStyle: 'short',
              }).format(new Date(initialValues.createdAt))}
            />
          ) : null}

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
