export default function DealDetail() {
  const { id } = useParams();
  const dealQuery = useDeal(id);
  const deal = dealQuery.data;

  const contactQueries = useQueries({
    queries: (deal?.contactLinks ?? []).map((contactLink) => ({
      queryKey: ['contacts', 'detail', contactLink.contactId],
      queryFn: () => contactApi.get(contactLink.contactId),
    })),
  });

  const contactNameById = new Map(
    contactQueries
      .map((query) => query.data)
      .filter(Boolean)
      .map((contact) => [contact.id, contact.name]),
  );

  return (
    <Stack spacing={2}>
      <IconButton component={Link} to="/deals" aria-label="Back to deals" shape="rounded">
        <ArrowLeftOutlined />
      </IconButton>

      <MainCard title={deal?.name || 'Deal detail'}>
