    dealRepository.findContactLinksByDealId.mockResolvedValue([
      { contactId: 'contact-1', role: 'decision-maker' },
      { contactId: 'contact-2', role: 'legal' },
    ]);

    const result = await service.getDealWithCompany('deal-id');

    expect(result).toMatchObject({
      id: 'deal-id',
      company: {
        id: 'company-id',
        name: 'Acme Corp',
      },
      primaryContactId: 'contact-1',
      contactLinks: [
        { contactId: 'contact-1', role: 'decision-maker' },
        { contactId: 'contact-2', role: 'legal' },
      ],
    });
    expect(result).not.toHaveProperty('contactId');
  });
});

import { HttpStatus } from '@nestjs/common';

export const BUSINESS_ERROR_CODES = {
  VALIDATION_ERROR: 'VALIDATION_ERROR',
  INVALID_UUID: 'INVALID_UUID',
  NOT_FOUND: 'NOT_FOUND',
  ENTITY_NOT_FOUND: 'ENTITY_NOT_FOUND',
  PARENT_NOT_FOUND: 'PARENT_NOT_FOUND',
  IMMUTABLE_FIELD: 'IMMUTABLE_FIELD',
  REFERENTIAL_INTEGRITY_VIOLATION: 'REFERENTIAL_INTEGRITY_VIOLATION',
  INVALID_LINK_STATE: 'INVALID_LINK_STATE',
} as const;

export type BusinessErrorCode =
  (typeof BUSINESS_ERROR_CODES)[keyof typeof BUSINESS_ERROR_CODES];

export const BUSINESS_ERROR_CATALOG: Record<
  BusinessErrorCode,
  {
    defaultStatusCode: number;
    description: string;
  }
> = {
  VALIDATION_ERROR: {
    defaultStatusCode: HttpStatus.BAD_REQUEST,
    description: 'Request payload or query validation failed.',
  },
  INVALID_UUID: {
    defaultStatusCode: HttpStatus.BAD_REQUEST,
    description: 'A route parameter is not a valid UUID v4.',
  },
  NOT_FOUND: {
    defaultStatusCode: HttpStatus.NOT_FOUND,
    description: 'The requested resource does not exist.',
  },
  ENTITY_NOT_FOUND: {
    defaultStatusCode: HttpStatus.NOT_FOUND,
    description: 'The requested entity does not exist.',
  },
  PARENT_NOT_FOUND: {
    defaultStatusCode: HttpStatus.NOT_FOUND,
    description: 'The required parent entity does not exist.',
  },
  IMMUTABLE_FIELD: {
    defaultStatusCode: HttpStatus.UNPROCESSABLE_ENTITY,
    description: 'The request attempts to modify an immutable field.',
  },
  REFERENTIAL_INTEGRITY_VIOLATION: {
    defaultStatusCode: HttpStatus.CONFLICT,
    description: 'The operation is blocked by related records.',
  },
  INVALID_LINK_STATE: {
    defaultStatusCode: HttpStatus.CONFLICT,
    description: 'The relationship link state is invalid for this operation.',
  },
};
import { HttpException } from '@nestjs/common';
import { BusinessErrorCode } from './error-codes';

export type AppExceptionOptions = {
  statusCode: number;
  code: BusinessErrorCode;
  message: string;
  details?: unknown;
};

export type AppExceptionPayload = {
  code: BusinessErrorCode;
  message: string;
  details?: unknown;
};

export class AppException extends HttpException {
  constructor(options: AppExceptionOptions) {
    const { statusCode, code, message, details } = options;

    super(
      {
        code,
        message,
        details,
      },
      statusCode,
    );
  }
}

