import { execSync } from 'node:child_process';
import { resolve } from 'node:path';
import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  resetDatabaseSchema,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Seed scenarios (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await resetDatabaseSchema();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    dataSource = await resetDatabaseSchema();
  });

  it('creates the demo seed with expected company/contact counts and pipeline coverage', async () => {
    // Verifies the demo seed creates baseline companies, contacts, and deals.
    runSeedCommand('pnpm db:reset:seed:demo');

    const [{ count: companyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Demo Seed Company%'
      `,
    );
    const [{ count: contactCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE "email" LIKE 'demo-contact-%@baseline.local'
      `,
    );
    const [{ count: dealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Demo Seed Deal%'
      `,
    );
    const [{ count: stageCount }] = await dataSource.query(
      `
        SELECT COUNT(DISTINCT "stage")::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Demo Seed Deal%'
      `,
    );
    const [{ count: multiCompanyContactCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM (
          SELECT link."contactId"
          FROM "contact_company_links" link
          GROUP BY link."contactId"
          HAVING COUNT(*) >= 2
             AND SUM(CASE WHEN link."isPrimary" THEN 1 ELSE 0 END) = 1
        ) multi_linked_contacts
      `,
    );
    const [{ count: threeContactDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM (
          SELECT link."dealId"
          FROM "deal_contact_links" link
          WHERE link."role" IN ('decision-maker', 'legal', 'it-lead')
          GROUP BY link."dealId"
          HAVING COUNT(*) >= 3
             AND COUNT(DISTINCT link."role") >= 3
        ) multi_contact_deals
      `,
    );

    expect(companyCount).toBe(10);
    expect(contactCount).toBe(33);
    expect(dealCount).toBeGreaterThanOrEqual(8);
    expect(stageCount).toBeGreaterThanOrEqual(4);
    expect(multiCompanyContactCount).toBeGreaterThanOrEqual(1);
    expect(threeContactDealCount).toBeGreaterThanOrEqual(1);
  });

  it('does not duplicate demo seed rows across reruns', async () => {
    // Verifies rerunning the demo seed does not duplicate baseline rows.
    runSeedCommand('pnpm db:reset:seed:demo');
    runSeedCommand('pnpm db:seed:demo');

    const [{ count: companyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Demo Seed Company%'
      `,
    );
    const [{ count: contactCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE "email" LIKE 'demo-contact-%@baseline.local'
      `,
    );
    const [{ count: dealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Demo Seed Deal%'
      `,
    );

    expect(companyCount).toBe(10);
    expect(contactCount).toBe(33);
    expect(dealCount).toBe(10);
  });

  it('creates edge-case seed data including null deal links', async () => {
    // Verifies edge-case seed covers nulls, long fields, and valid links.
    runSeedCommand('pnpm db:reset:seed:edge-case');

    const [{ count: companyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Edge Seed Company%'
           OR "name" LIKE 'Edge Seed Company Long Name%'
      `,
    );
    const [{ count: emptyCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies" company
        WHERE company.name = 'Edge Seed Company 00 Empty Contacts'
          AND NOT EXISTS (
            SELECT 1
            FROM "contacts" contact
            WHERE contact."companyId" = company.id
          )
      `,
    );
    const [{ count: nullFieldCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" = 'Edge Seed Company 01 Missing Fields'
          AND "email" IS NULL
          AND "phone" IS NULL
          AND "website" IS NULL
      `,
    );
    const [{ count: longNameCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Edge Seed Company Long Name%'
          AND LENGTH("name") >= 250
      `,
    );
    const [{ count: maxLengthRoleCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE LENGTH(COALESCE("role", '')) = 100
      `,
    );
    const [{ count: orphanContactCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts" contact
        LEFT JOIN "companies" company ON company.id = contact."companyId"
        WHERE company.id IS NULL
      `,
    );
    const [{ count: zeroLinkedContactDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals" deal
        WHERE deal."name" LIKE 'Edge Seed Deal%'
          AND NOT EXISTS (
            SELECT 1
            FROM "deal_contact_links" link
            WHERE link."dealId" = deal.id
          )
      `,
    );
    const [{ count: nullDealExpectedCloseDateCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Edge Seed Deal%'
          AND "expectedCloseDate" IS NULL
      `,
    );

    expect(companyCount).toBe(25);
    expect(emptyCompanyCount).toBe(1);
    expect(nullFieldCount).toBe(1);
    expect(longNameCompanyCount).toBeGreaterThanOrEqual(1);
    expect(maxLengthRoleCount).toBeGreaterThanOrEqual(1);
    expect(orphanContactCount).toBe(0);
    expect(zeroLinkedContactDealCount).toBeGreaterThanOrEqual(1);
    expect(nullDealExpectedCloseDateCount).toBeGreaterThanOrEqual(1);
  });
});

function runSeedCommand(command: string) {
  execSync(command, {
    cwd: resolve(__dirname, '..'),
    stdio: 'pipe',
  });
}

