import { CompanyEntity } from '../../modules/company/company.entity';
import { ContactEntity } from '../../modules/contact/contact.entity';
import { DealEntity } from '../../modules/deal/deal.entity';
import { SeedContext } from './seed.types';

export const daysAgo = (now: Date, days: number) => {
  const date = new Date(now);

  date.setDate(date.getDate() - days);

  return date;
};

export const distributeRecentDate = (
  now: Date,
  index: number,
  total: number,
) => {
  const safeTotal = Math.max(total - 1, 1);
  const offsetDays = Math.round((index / safeTotal) * 29);
  const date = daysAgo(now, offsetDays);

  date.setHours(9 + (index % 8), (index * 7) % 60, 0, 0);

  return date;
};

export const resetSeedTables = async ({ dataSource }: SeedContext) => {
  await dataSource.query(
    'TRUNCATE TABLE "deal_contact_links", "contact_company_links", "deals", "contacts", "companies" RESTART IDENTITY CASCADE',
  );
};

export const cleanupCompaniesByPrefixes = async (
  { dataSource }: SeedContext,
  prefixes: string[],
) => {
  if (prefixes.length === 0) {
    return;
  }

  const companyRepository = dataSource.getRepository(CompanyEntity);
  const dealRepository = dataSource.getRepository(DealEntity);
  const companies = await companyRepository
    .createQueryBuilder('company')
    .select('company.id', 'id')
    .where(
      prefixes
        .map((_, index) => `company.name LIKE :prefix${index}`)
        .join(' OR '),
      Object.fromEntries(
        prefixes.map((prefix, index) => [`prefix${index}`, `${prefix}%`]),
      ),
    )
    .getRawMany<{ id: string }>();

  if (companies.length === 0) {
    return;
  }

  const companyIds = companies.map(({ id }) => id);

  const deals = await dealRepository
    .createQueryBuilder('deal')
    .select('deal.id', 'id')
    .where('deal.companyId IN (:...ids)', { ids: companyIds })
    .getRawMany<{ id: string }>();

  if (deals.length > 0) {
    await dataSource
      .createQueryBuilder()
      .delete()
      .from('deal_contact_links')
      .where('"dealId" IN (:...dealIds)', {
        dealIds: deals.map(({ id }) => id),
      })
      .execute();
  }

  await dealRepository
    .createQueryBuilder()
    .delete()
    .where('companyId IN (:...ids)', { ids: companies.map(({ id }) => id) })
    .execute();

  const contacts = await dataSource
    .getRepository(ContactEntity)
    .createQueryBuilder('contact')
    .select('contact.id', 'id')
    .where('contact.companyId IN (:...ids)', { ids: companyIds })
    .getRawMany<{ id: string }>();

  if (contacts.length > 0) {
    await dataSource
      .createQueryBuilder()
      .delete()
      .from('contact_company_links')
      .where('"contactId" IN (:...contactIds)', {
        contactIds: contacts.map(({ id }) => id),
      })
      .execute();
  }

  await dataSource
    .createQueryBuilder()
    .delete()
    .from('contact_company_links')
    .where('"companyId" IN (:...companyIds)', { companyIds })
    .execute();

  await dataSource
    .getRepository(ContactEntity)
    .createQueryBuilder()
    .delete()
    .where('companyId IN (:...ids)', { ids: companies.map(({ id }) => id) })
    .execute();

  await companyRepository
    .createQueryBuilder()
    .delete()
    .where('id IN (:...ids)', { ids: companies.map(({ id }) => id) })
    .execute();
};

